select
t.*
from refund t

    t.del_flag = 0

        and t.`id` like CONCAT('%',#{query.id},'%')


        and t.`channel_id` = #{query.channelId}


        and t.`supplier_id` = #{query.supplierId}


        and t.`id` in

            #{item}



        and t.`spu_order_no` = #{query.spuOrderNo}


        and t.`from_order_state` not in

            #{item}



        and t.`order_type` = #{query.orderType}


        and t.`member_id` = #{query.memberId}


        and t.`refund_type` = #{query.refundType}


        and t.`refund_state` = #{query.refundState}


        and t.`refund_state` in

            #{item}



        and UNIX_TIMESTAMP(t.create_time) * 1000  >=  #{query.createBeginTime}


        and UNIX_TIMESTAMP(t.create_time) * 1000  <=  #{query.createEndTime}


        and t.`state_time` < #{query.stateTimeLess}


        and JSON_EXTRACT(t.item, '$[*].spuName') LIKE CONCAT('%',#{query.spuName},'%')
